    $("#l-kind").addEventListener("change", toggleParentVisibility);

    $("#export-btn").addEventListener("click", exportJSON);
    $("#history-save-btn").addEventListener("click", saveVersion);
    const clearHistoryBtn = $("#history-clear-btn");
